before:
Complete local Rust example; the app itself does not execute it:
```rust
trait Label { fn label(&self) -> &str; }
struct Topic;
impl Label for Topic { fn label(&self) -> &str { "topic" } }
fn generic<T: Label>(value: &T) { println!("{}", value.label()); }
fn dynamic(value: &dyn Label) { println!("{}", value.label()); }
fn main() { let value = Topic; generic(&value); dynamic(&value); }
```

